DO $pre$ BEGIN
 IF (SELECT count(*) FROM _u)<>31 OR (SELECT count(DISTINCT code) FROM _u)<>31
 OR (SELECT sum(jsonb_array_length(placements)) FROM _u)<>31 OR (SELECT count(*) FROM _p)<>51 OR (SELECT count(*) FROM _pl)<>51
 OR (SELECT sum(u.ects) FROM _u u WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(u.placements) e WHERE e->>'role'='mandatory'))<>162
 OR (SELECT count(DISTINCT e->>'group') FROM _u u, jsonb_array_elements(u.placements) e WHERE e->>'role'='alternative')<>3
 OR EXISTS(SELECT 1 FROM _u WHERE ects<>6)
 OR EXISTS(SELECT 1 FROM _pl WHERE confidence NOT IN ('alta','média'))
 THEN RAISE EXCEPTION 'Unexpected Matemática Aplicada manifest counts or ECTS (expected 162 mandatory + 3 option groups of 6 = 180)'; END IF;
 IF EXISTS(SELECT 1 FROM _p WHERE id !~ '^PL[A-Za-z0-9_-]{10,60}$' OR url<>'https://www.youtube.com/playlist?list='||id
 OR length(trim(title))<3 OR videos<4 OR language NOT IN('pt-PT','pt-BR','en'))
 OR EXISTS(SELECT 1 FROM _pl t LEFT JOIN _p p ON p.id=t.playlist_id LEFT JOIN _u u ON u.code=t.code WHERE p.id IS NULL OR u.code IS NULL)
 THEN RAISE EXCEPTION 'Invalid playlist metadata or link'; END IF;
 IF EXISTS(SELECT 1 FROM facodi.courses WHERE (code='LMAEG' OR slug='matematica-aplicada-economia-gestao'
 OR (external_source='ualg_official' AND external_id='1839')) AND id<>md5('facodi:ualg:1839:course:record')::uuid)
 THEN RAISE EXCEPTION 'Another course already uses LMAEG, the slug or UAlg 1839; reconcile manually'; END IF;
END $pre$;

