-- A UC code that is already the slug of a unit in another course gets the prefix matematica-aplicada-uc-; otherwise the slug is the code.
INSERT INTO facodi.curricular_units(id,learning_object_id,course_id,code,external_source,external_id,slug,title,normalized_title,summary,
 description_html,year,semester,ects,position,language,source_url,plan_url,status,published,metadata)
SELECT md5('facodi:ualg:1839:uc:record:'||u.code)::uuid,md5('facodi:ualg:1839:uc:'||u.code)::uuid,md5('facodi:ualg:1839:course:record')::uuid,
 u.code,'ualg_official','1839:'||u.code,
 CASE WHEN EXISTS(SELECT 1 FROM facodi.curricular_units o WHERE o.slug=u.code AND o.course_id<>md5('facodi:ualg:1839:course:record')::uuid)
 THEN 'matematica-aplicada-uc-'||u.code ELSE u.code END,
 u.title,u.title,u.summary,'<p>'||u.summary||'</p><p><strong>Temas:</strong> '||array_to_string(u.topics,'; ')||'.</p>',
 u.year,u.semester,u.ects,u.position,'pt','https://www.ualg.pt/curso/1839/plano','https://www.ualg.pt/curso/1839/plano','active',true,
 jsonb_build_object('course_code','LMAEG','official_course_id','1839','official_unit_code',u.code,'academic_year','2026/27',
 'official_plan_url','https://www.ualg.pt/curso/1839/plano','official_fuc_url',u.fuc_url,'detailed_fuc_checked',u.fuc_url IS NOT NULL,
 'official_code_checked',true,'official_ects_checked',true,'official_semester_checked',true,
 'offered_in_both_semesters',u.offered_both_terms,'is_annual',u.semester IS NULL,'official_plan_note',u.plan_note,
 'is_elective_option',u.elective_only,'official_option_group',u.option_group,
 'curriculum_placements',u.placements,'study_topics',to_jsonb(u.topics),'source_quality','ualg_official_structure',
 'curriculum_review_status','approved_official_plan','curation_batch','facodi_ualg_1839_matematica_aplicada_economia_gestao_20261118')
FROM _u u
ON CONFLICT DO NOTHING;

