-- Playlists: reutiliza um registo existente com o mesmo ID do YouTube; senão cria um novo.
INSERT INTO facodi.learning_objects(id,object_type,title,slug,description,language,status,published,source_type,source_url,source_id,tags,metadata)
SELECT md5('facodi:ualg:1839:playlist:'||p.id)::uuid,'playlist',p.title,'facodi-uc-playlist-'||p.id,p.description,p.language,
 'active',true,'youtube',p.url,p.id,p.tags,
 jsonb_build_object('source_channel',p.channel,'source_channel_url',p.channel_url,'youtube_playlist_id',p.id,
 'video_count_at_verification',p.videos,'playlist_title_checked',true,'playlist_owner_verified',true,
 'owner_verification_method','youtube_oembed','items_channel_checked',true,'playlist_membership_verified',false,
 'items_automatically_imported',false,'verified_on','2026-11-18','curation_batch','facodi_ualg_1839_matematica_aplicada_economia_gestao_20261118')
FROM _p p
WHERE NOT EXISTS(SELECT 1 FROM facodi.learning_objects lo WHERE lo.object_type='playlist' AND lo.source_type='youtube' AND lo.source_id=p.id)
ON CONFLICT DO NOTHING;

INSERT INTO facodi.learning_object_relations(id,parent_object_id,child_object_id,relation_type,position,created_by_mechanism,metadata)
SELECT md5('facodi:ualg:1839:uc-playlist:'||x.code||':'||x.playlist_id)::uuid,md5('facodi:ualg:1839:uc:'||x.code)::uuid,lo.id,
 'contains',91000+x.ord,'structured_catalog_import',
 jsonb_build_object('review_status','approved','review_scope','uc_programme_topic_match','match_confidence',x.confidence,
 'content_level',x.level,'match_rationale',x.match,'curation_batch','facodi_ualg_1839_matematica_aplicada_economia_gestao_20261118','playlist_owner_verified',true,'members_verified',false)
FROM _pl x
JOIN LATERAL (SELECT id FROM facodi.learning_objects WHERE object_type='playlist' AND source_type='youtube' AND source_id=x.playlist_id
 ORDER BY id LIMIT 1) lo ON true
ON CONFLICT DO NOTHING;

DO $post$ DECLARE units integer; links integer; BEGIN
 SELECT count(*) INTO units FROM facodi.curricular_units
 WHERE course_id=md5('facodi:ualg:1839:course:record')::uuid AND published AND status='active' AND learning_object_id IS NOT NULL
 AND jsonb_array_length(metadata->'curriculum_placements')>0;
 SELECT count(*) INTO links FROM _pl x JOIN facodi.learning_object_relations r ON r.parent_object_id=md5('facodi:ualg:1839:uc:'||x.code)::uuid
 AND r.relation_type='contains' JOIN facodi.learning_objects lo ON lo.id=r.child_object_id AND lo.object_type='playlist' AND lo.source_id=x.playlist_id;
 IF NOT EXISTS(SELECT 1 FROM facodi.courses WHERE code='LMAEG' AND published AND status='active' AND ects_total=180)
 OR units<>31 OR links<>51
 THEN RAISE EXCEPTION 'Matemática Aplicada import not complete: units %, playlist links %',units,links; END IF;
END $post$;
